insert into public.reading_exercises(preset_key,content) values
('dogs-missing', '{"title":"Dog Detectives · Disappearing Words","passage":"Dogs have been human companions for thousands of years, developing into hundreds of distinct breeds designed for specific jobs. Working breeds like the German Shepherd are famous for being exceptionally attentive. They stay focused on their surroundings, watching their owners closely for commands. Other dogs, like the energetic Jack Russell Terrier, can bring utter chaos into a quiet home if they do not get enough daily exercise to burn off their boundless energy.\n\nWhen observing different breeds, paying attention to a dog''s posture is essential. A broad-chested English Mastiff stands tall to signal confidence, whereas a frightened chihuahua might lower its body when scared. If an unfamiliar animal enters a guard dog''s territory, the dog might adopt a ferocious stance to warn the intruder away. However, well-trained dogs learn to yield to their handlers, stepping back and yielding control whenever given a command.\n\nThroughout history, humans have formed deep emotional bonds with their pets. A man might fondly look back on his boyhood, remembering the loyal Golden Retriever that followed him on every childhood adventure. Yet, dogs also experience powerful emotions. During loud thunderstorms or firework displays, a panicked hound might sprint frantically across the yard looking for shelter, while a hysterical lapdog might bark uncontrollably until comforted by its owner.\n\nResponsibility is crucial when caring for any breed. Leaving a dog trapped inside a hot car on a summer day is pure torture for the animal and can cause severe harm. In fact, doing so is illegal in many places, carrying heavy fines or criminal charges. Understanding each breed''s unique traits helps ensure every dog lives a safe, healthy, and happy life alongside its human family.","strategy":"missing","mode":"type","targetWords":["chaos","illegal","torture","posture","hysterical","attentive","boyhood","panicked","ferocious","yield"],"vocabulary":{"chaos":{"synonym":"disorder","definition":"A state of complete confusion or disorder."},"illegal":{"synonym":"unlawful","definition":"Not allowed by law."},"torture":{"synonym":"agony","definition":"Severe physical or mental suffering."},"posture":{"synonym":"stance","definition":"The position in which a body is held."},"hysterical":{"synonym":"uncontrollable","definition":"So overwhelmed by emotion that it is hard to stay calm."},"attentive":{"synonym":"watchful","definition":"Paying close attention to what is happening."},"boyhood":{"synonym":"childhood","definition":"The time in a boy''s life before he becomes an adult."},"panicked":{"synonym":"terrified","definition":"Suddenly filled with fear and unable to think calmly."},"ferocious":{"synonym":"fierce","definition":"Very fierce or threatening."},"yield":{"synonym":"surrender","definition":"To give way or let someone else take control."}},"challenges":[{"index":60,"word":"attentive","effect":"missing","shown":"_________"},{"index":108,"word":"chaos","effect":"missing","shown":"_____"},{"index":164,"word":"posture","effect":"missing","shown":"_______"},{"index":236,"word":"ferocious","effect":"missing","shown":"_________"},{"index":260,"word":"yield","effect":"missing","shown":"_____"},{"index":324,"word":"boyhood","effect":"missing","shown":"_______"},{"index":376,"word":"panicked","effect":"missing","shown":"________"},{"index":402,"word":"hysterical","effect":"missing","shown":"__________"},{"index":466,"word":"torture","effect":"missing","shown":"_______"},{"index":494,"word":"illegal","effect":"missing","shown":"_______"}]}'::jsonb),
